#ifndef MEP_SCHEME_LSP_H
#define MEP_SCHEME_LSP_H

// The analysis half of mep's own Scheme language server (the wire half is
// scheme_lsp_server.cpp, the `mep-scheme-lsp` binary; the `scheme_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (scheme_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct SchemeLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class SchemeLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const SchemeLspDocument> SchemeLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class SchemeLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct SchemeLspDiagnostic {
    SchemeLspRange range;
    SchemeLspSeverity severity = SchemeLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<SchemeLspDiagnostic> SchemeLspDiagnostics(const SchemeLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string SchemeLspFormatDiagnostic(const std::string &path, const SchemeLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool SchemeLspDiagnosticFails(const SchemeLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class SchemeLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct SchemeLspCompletionItem {
    std::string label;
    std::string insert_text;
    SchemeLspKind kind = SchemeLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<SchemeLspCompletionItem> SchemeLspCompletions(const SchemeLspDocument &doc, int line, int col);

struct SchemeLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    SchemeLspRange range;
};

SchemeLspHoverInfo SchemeLspHover(const SchemeLspDocument &doc, int line, int col);

struct SchemeLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

SchemeLspSignatureHelp SchemeLspSignatureAt(const SchemeLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct SchemeLspLocation {
    SchemeLspRange range;
};

std::vector<SchemeLspLocation> SchemeLspDefinition(const SchemeLspDocument &doc, int line, int col);

struct SchemeLspReference {
    SchemeLspRange range;
    bool is_definition = false;
};

std::vector<SchemeLspReference> SchemeLspReferences(const SchemeLspDocument &doc, int line, int col);

struct SchemeLspTextEdit {
    SchemeLspRange range;
    std::string new_text;
};

struct SchemeLspRenameTarget {
    bool found = false;
    SchemeLspRange range;
    std::string placeholder;
};

SchemeLspRenameTarget SchemeLspPrepareRename(const SchemeLspDocument &doc, int line, int col);
std::vector<SchemeLspTextEdit> SchemeLspRename(const SchemeLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class SchemeLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct SchemeLspSymbol {
    std::string name;
    std::string detail;
    SchemeLspSymbolKind kind = SchemeLspSymbolKind::Variable;
    SchemeLspRange range;
    SchemeLspRange sel_range;
    int parent = -1;
};

std::vector<SchemeLspSymbol> SchemeLspSymbols(const SchemeLspDocument &doc);

struct SchemeLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<SchemeLspFold> SchemeLspFolds(const SchemeLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<SchemeLspTextEdit> SchemeLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_SCHEME_LSP_H
